<script setup>
import {computed,ref,watch} from 'vue'
const props=defineProps({mode:String,clients:Array,catalogs:Object,api:Function})
const emit=defineEmits(['refresh','edit','create'])
const kind=ref('categories'), search=ref(''),status=ref('all'),category=ref('all'),page=ref(1),view=ref('table'),sort=ref('name'),dialog=ref(null),editing=ref(null),record=ref({}),saving=ref(false),error=ref(''),toast=ref('')
const titles={categories:'Categorías',designs:'Diseños',lines:'Líneas visuales',networks:'Redes y enlaces'}
const descriptions={categories:'Organiza tus clientes por especialidad y colección visual.',designs:'Ponle nombre a las variantes que dan personalidad a tus tarjetas.',lines:'Administra el estilo de presentación de cada marca.',networks:'Todos tus canales de contacto, listos para conectar.'}
const categoryNames=computed(()=>Object.fromEntries((props.catalogs.categories||[]).map(c=>[c.code,c.label])))
const isClients=computed(()=>props.mode==='clients')
const rows=computed(()=>{
 let data=isClients.value?props.clients:(props.catalogs[kind.value]||[])
 data=data.filter(r=>{const text=isClients.value?[r.company_name,r.username,r.contact_email,categoryNames.value[r.category]].join(' '):[r.label,r.code,r.description,r.value].join(' ');return text.toLowerCase().includes(search.value.toLowerCase())&&(status.value==='all'||(isClients.value?clientStatus(r)===status.value:String(r.active)===status.value))&&(!isClients.value||category.value==='all'||r.category===category.value)})
 return [...data].sort((a,b)=>sort.value==='updated'?String(b.updated_at||'').localeCompare(a.updated_at||''):String(isClients.value?a.company_name:a.label).localeCompare(String(isClients.value?b.company_name:b.label),'es'))
})
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/8)))
const visible=computed(()=>rows.value.slice((page.value-1)*8,page.value*8))
const generated=computed(()=>props.clients.filter(c=>c.generated).length)
const activeCount=computed(()=>Object.values(props.catalogs).flat().filter(x=>x.active).length)
const options=computed(()=>kind.value==='categories'?['abogados','ingenieria','belleza','nutricion','arquitectura']:kind.value==='designs'?Array.from({length:7},(_,i)=>'Estilo '+(i+1)):['Auto','Formal','Moderna','Buchona','Lujo','Minimalista'])
watch([search,status,category,kind,()=>props.mode],()=>{page.value=1;error.value='';toast.value=''})
watch(pages,v=>{if(page.value>v)page.value=v})
function clientStatus(c){return !c.generated?'draft':c.stale?'pending':'ready'}
function statusLabel(c){return {draft:'Borrador',pending:'Por regenerar',ready:'Generada'}[clientStatus(c)]}
function initials(name){return(name||'').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function newRecord(){editing.value=null;record.value={code:'',label:'',description:'',active:true,value:options.value[0]||''};error.value='';dialog.value='catalog'}
function editRecord(r){editing.value=r.code;record.value={...r};dialog.value='catalog';error.value=''}
function makeCode(){if(!editing.value)record.value.code=record.value.label.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)}
function close(){if(!saving.value){dialog.value=null;error.value=''}}
async function persist(){saving.value=true;error.value='';try{await props.api('/catalogs/'+kind.value+(editing.value?'/'+editing.value:''),editing.value?'PUT':'POST',record.value);await emitRefresh();dialog.value=null;toast.value='Catálogo actualizado correctamente.'}catch(e){error.value=e.message}finally{saving.value=false}}
async function emitRefresh(){await props.api('/catalogs').then(c=>emit('refresh',c));}
function askDelete(r){record.value=r;dialog.value='delete';error.value=''}
async function deleteRecord(){saving.value=true;error.value='';try{await props.api(isClients.value?'/clients/'+record.value.username:'/catalogs/'+kind.value+'/'+record.value.code,'DELETE',{});await emitRefresh();dialog.value=null;toast.value='Registro eliminado.'}catch(e){error.value=e.message}finally{saving.value=false}}
function inspect(r){record.value=r;dialog.value='detail'}
function editClient(r){dialog.value=null;emit('edit',r)}
function date(value){return value?new Date(value.replace(' ','T')+'Z').toLocaleDateString('es-MX',{day:'numeric',month:'short',year:'numeric'}):'—'}
</script>
<template>
<section class="management">
 <div class="manage-heading"><div><span class="eyebrow">TU ESPACIO CREATIVO</span><h1>{{isClients?'Cada conexión empieza aquí.':'Todo en su lugar.'}}</h1><p>{{isClients?'Administra tus clientes y transforma su identidad en una tarjeta única.':'Catálogos que mantienen tu estudio ordenado y tus diseños consistentes.'}}</p></div><button class="primary large" @click="isClients?emit('create'):newRecord()">＋ {{isClients?'Nuevo cliente':'Nuevo registro'}}</button></div>
 <div class="dashboard-metrics"><article><div class="metric-top"><span>{{isClients?'Clientes en el estudio':'Registros de catálogo'}}</span><i class="metric-symbol">▤</i></div><strong>{{isClients?clients.length:Object.values(catalogs).flat().length}}</strong><p>{{isClients?'Identidades listas para conectar':'Tu biblioteca de configuración'}}</p></article><article><div class="metric-top"><span>{{isClients?'Tarjetas generadas':'Registros activos'}}</span><i class="metric-symbol mint">✓</i></div><strong>{{isClients?generated:activeCount}}</strong><p>{{isClients?'Con QR y contacto descargable':'Disponibles en el editor'}}</p></article><article class="metric-feature"><div class="metric-top"><span>{{isClients?'Un diseño para cada marca':'Organización sin complicaciones'}}</span><i>✦</i></div><strong>{{isClients?'35 diseños':'4 catálogos'}}</strong><p>{{isClients?'Cinco especialidades. Infinitas conexiones.':'Categorías, diseños, líneas y redes.'}}</p></article></div>
 <div v-if="toast" class="notice success" role="status">{{toast}}</div>
 <div v-if="!isClients" class="catalog-switch"><button v-for="(title,key) in titles" :key="key" :class="{chosen:kind===key}" @click="kind=key;status='all'"><span>{{{categories:'◈',designs:'▧',lines:'◐',networks:'◎'}[key]}}</span><strong>{{title}}</strong><small>{{(catalogs[key]||[]).length}} registros</small></button></div>
 <section class="directory panel">
  <div class="directory-title"><div><h2>{{isClients?'Directorio de clientes':titles[kind]}} <span class="total-pill">{{rows.length}}</span></h2><p>{{isClients?'Consulta, edita y entrega sin perder de vista ningún detalle.':descriptions[kind]}}</p></div><div v-if="isClients" class="view-toggle" aria-label="Presentación"><button :class="{chosen:view==='table'}" @click="view='table'" aria-label="Vista de tabla">☷</button><button :class="{chosen:view==='cards'}" @click="view='cards'" aria-label="Vista de tarjetas">▦</button></div></div>
  <div class="directory-tools"><label class="directory-search"><span class="sr-only">Buscar registros</span><input v-model="search" :placeholder="isClients?'Buscar por nombre, correo o URL…':'Buscar en '+titles[kind].toLowerCase()+'…'"></label><label v-if="isClients"><span class="sr-only">Filtrar categoría</span><select v-model="category"><option value="all">Todas las categorías</option><option v-for="c in catalogs.categories" :value="c.code">{{c.label}}</option></select></label><label><span class="sr-only">Filtrar estado</span><select v-model="status"><option value="all">Todos los estados</option><template v-if="isClients"><option value="ready">Generada</option><option value="draft">Borrador</option><option value="pending">Por regenerar</option></template><template v-else><option value="true">Activos</option><option value="false">Inactivos</option></template></select></label><label v-if="isClients"><span class="sr-only">Ordenar registros</span><select v-model="sort"><option value="name">Nombre A–Z</option><option value="updated">Más recientes</option></select></label></div>
  <div v-if="!rows.length" class="directory-empty"><span>⌕</span><h3>{{search||status!=='all'||category!=='all'?'No encontramos coincidencias':isClients?'Aquí comienza tu próximo proyecto':'Tu catálogo está listo para crecer'}}</h3><p>{{search?'Prueba con otro nombre o ajusta los filtros.':'Crea tu primer registro para comenzar.'}}</p><button class="secondary" @click="search='';status='all';category='all'" v-if="search||status!=='all'||category!=='all'">Limpiar filtros</button><button v-else class="primary" @click="isClients?emit('create'):newRecord()">Crear registro</button></div>
  <div v-else-if="isClients&&view==='cards'" class="client-grid"><article v-for="c in visible" :key="c.username"><div class="card-top"><span class="directory-avatar">{{initials(c.company_name)}}</span><span class="state-badge" :class="clientStatus(c)">{{statusLabel(c)}}</span></div><h3>{{c.company_name}}</h3><p>{{categoryNames[c.category]||c.category}}</p><span class="url-caption">/{{c.username}}</span><div class="card-actions"><button class="secondary" @click="inspect(c)">Ver detalles</button><button class="primary" @click="editClient(c)">Editar</button></div></article></div>
  <div v-else class="table-scroll"><table><thead><tr><th>{{isClients?'CLIENTE':'REGISTRO'}}</th><th>{{isClients?'CATEGORÍA':'CONFIGURACIÓN'}}</th><th>ESTADO</th><th>{{isClients?'ACTUALIZACIÓN':'EN USO'}}</th><th class="actions-col">ACCIONES</th></tr></thead><tbody><tr v-for="r in visible" :key="r.username||r.code"><td><div class="table-identity"><span class="directory-avatar" :class="{catalog:!isClients}">{{isClients?initials(r.company_name):kind==='networks'?'◎':'◈'}}</span><div><button class="name-link" @click="isClients?inspect(r):editRecord(r)">{{isClients?r.company_name:r.label}}</button><small>{{isClients?'/'+r.username:r.code}}</small></div></div></td><td><span v-if="isClients" class="category-tag">{{categoryNames[r.category]||r.category}}</span><template v-else><strong class="config-value">{{r.value}}</strong><small class="description-cell">{{r.description||'Sin descripción'}}</small></template></td><td><span class="state-badge" :class="isClients?clientStatus(r):r.active?'ready':'draft'">{{isClients?statusLabel(r):r.active?'Activo':'Inactivo'}}</span></td><td class="date-cell">{{isClients?date(r.updated_at):r.usage+' clientes'}}</td><td><div class="row-actions"><button v-if="isClients" @click="inspect(r)" class="row-icon" aria-label="Ver detalles" title="Ver detalles">◎</button><button @click="isClients?editClient(r):editRecord(r)" class="row-icon" aria-label="Editar registro" title="Editar">✎</button><a v-if="isClients&&r.generated" :href="'/api/clients/'+r.username+'/export'" class="row-icon" aria-label="Descargar tarjeta" title="Descargar ZIP">↓</a><button @click="askDelete(r)" class="row-icon danger-icon" aria-label="Eliminar registro" title="Eliminar">×</button></div></td></tr></tbody></table></div>
  <div class="pagination"><span>{{rows.length?((page-1)*8+1)+'–'+Math.min(page*8,rows.length):'0'}} de {{rows.length}} registros</span><div><button :disabled="page===1" @click="page--">Anterior</button><span>{{page}} / {{pages}}</span><button :disabled="page===pages" @click="page++">Siguiente</button></div></div>
 </section>
 <div class="management-foot"><span>✦ Hecho para trabajar con orden y crear con libertad.</span><a href="/api/backup">Descargar respaldo del estudio</a></div>
 <Teleport to="body"><div v-if="dialog" class="modal-overlay" @click.self="close" @keydown.esc="close"><section class="studio-modal" role="dialog" aria-modal="true" :aria-label="dialog==='catalog'?'Editar catálogo':dialog==='delete'?'Confirmar eliminación':'Detalle del cliente'" tabindex="-1"><div class="modal-header"><div><span class="eyebrow">{{dialog==='delete'?'CONFIRMAR ACCIÓN':dialog==='detail'?'FICHA DEL CLIENTE':titles[kind]}}</span><h2>{{dialog==='catalog'?(editing?'Editar registro':'Nuevo registro'):dialog==='delete'?'¿Eliminar este registro?':record.company_name}}</h2></div><button class="icon-button" @click="close" :disabled="saving" aria-label="Cerrar diálogo">×</button></div><div v-if="error" class="notice error" role="alert">{{error}}</div>
 <form v-if="dialog==='catalog'" @submit.prevent="persist"><fieldset :disabled="saving"><div class="fields"><label class="wide">Nombre visible<input v-model="record.label" @input="makeCode" required maxlength="100" placeholder="Nombre del registro" autofocus></label><label>Código único<input v-model="record.code" :disabled="!!editing" required maxlength="50" pattern="[a-z0-9][a-z0-9_\-]{0,49}"><small>No cambia después de guardar.</small></label><label>{{kind==='categories'?'Colección visual base':'Valor para el editor'}}<input v-if="kind==='networks'" v-model="record.value" required maxlength="100" placeholder="Nombre del canal"><select v-else v-model="record.value"><option v-for="option in options" :value="option">{{kind==='categories'?({abogados:'Abogacía',ingenieria:'Ingeniería',belleza:'Belleza',nutricion:'Nutrición',arquitectura:'Arquitectura'}[option]):option}}</option></select></label><label class="wide">Descripción<textarea v-model="record.description" rows="3" maxlength="500" placeholder="Una breve nota para tu equipo…"></textarea></label><label class="check-label wide"><input type="checkbox" v-model="record.active"><span>Disponible en el editor<small>Al desactivarlo, las tarjetas existentes se conservan.</small></span></label></div></fieldset><div class="modal-footer"><button type="button" class="secondary" @click="close" :disabled="saving">Cancelar</button><button class="primary" :disabled="saving">{{saving?'Guardando…':'Guardar registro'}}</button></div></form>
 <template v-if="dialog==='delete'"><p class="modal-copy">{{isClients?'Se eliminará el cliente y su tarjeta local. Los archivos originales de la versión anterior se conservan.':'Solo puedes eliminar registros que no estén en uso. También puedes desactivarlos desde Editar.'}}</p><div class="delete-target">{{record.company_name||record.label}}</div><p class="modal-copy">Esta acción no se puede deshacer. Descarga un respaldo si necesitas conservarlo.</p><div class="modal-footer"><button class="secondary" @click="close" :disabled="saving">Cancelar</button><button class="danger-button" @click="deleteRecord" :disabled="saving">{{saving?'Eliminando…':'Eliminar registro'}}</button></div></template>
 <template v-if="dialog==='detail'"><div class="detail-hero"><span class="directory-avatar">{{initials(record.company_name)}}</span><div><strong>{{categoryNames[record.category]}}</strong><small>/{{record.username}}</small></div><span class="state-badge" :class="clientStatus(record)">{{statusLabel(record)}}</span></div><p class="modal-copy">{{record.bio||'Sin biografía todavía.'}}</p><dl class="detail-grid"><div><dt>Nombre completo</dt><dd>{{record.full_name||'Sin especificar'}}</dd></div><div><dt>Especialidad</dt><dd>{{record.job_title||'Sin especificar'}}</dd></div><div><dt>Correo</dt><dd>{{record.contact_email||'Sin especificar'}}</dd></div><div><dt>Teléfono</dt><dd>{{record.contact_phone||'Sin especificar'}}</dd></div><div><dt>Diseño</dt><dd>{{record.theme_variant}} · {{record.design_line}}</dd></div><div><dt>Enlaces activos</dt><dd>{{record.links?.filter(l=>l.active).length||0}}</dd></div></dl><div class="detail-delivery" v-if="record.generated"><a :href="'/cards/'+record.username+'/'" target="_blank" rel="noopener">Abrir tarjeta ↗</a><a :href="'/api/clients/'+record.username+'/export'">Descargar ZIP</a></div><div class="modal-footer"><button class="secondary" @click="close">Cerrar</button><button class="primary" @click="editClient(record)">Editar tarjeta</button></div></template>
 </section></div></Teleport>
</section>
</template>
